package com.example.starter.trace.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;
import java.time.ZoneId;

/**
 * 追溯服务基础配置：统一使用 Asia/Shanghai 时钟，测试可替换为可控时钟。
 */
@Configuration
public class TraceConfig {

    /**
     * 业务时钟，所有时间戳经由此 Clock 写入，便于测试注入固定时钟。
     */
    @Bean
    public Clock traceClock() {
        return Clock.system(ZoneId.of("Asia/Shanghai"));
    }
}

package com.example.starter.trace.service;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与中文错误信息，由全局异常处理器转换为响应。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus status;

    public BusinessException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static BusinessException notFound(String message) {
        return new BusinessException(HttpStatus.NOT_FOUND, message);
    }

    public static BusinessException conflict(String message) {
        return new BusinessException(HttpStatus.CONFLICT, message);
    }

    public static BusinessException unprocessable(String message) {
        return new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }

    public static BusinessException badRequest(String message) {
        return new BusinessException(HttpStatus.BAD_REQUEST, message);
    }
}

